INSERT INTO financial_product(company_id,product_type,product_name,join_way,saving_type,loan_type,special_condition,join_member,min_rate,max_rate,max_limit,baseline_performance,max_benefit_limit,description,benefits,synced_at) SELECT c.company_id,'CARD','카카오뱅크 신한카드 Time','카카오뱅크 앱',NULL,NULL,'세부 할인·적립 제외 대상, 실적 산정, 월/건별 한도는 카드사 상품설명서와 공식 페이지 기준.','카드사 발급심사 기준 충족 고객',NULL,NULL,NULL,400000,50000,'시간대별 소비 10%, 대중교통 10%, 카카오T 택시 할인 중심 제휴 신용카드.','[{"category":"TIME_ZONE","discountRate":10.0,"description":"시간대별 대상 소비 할인","limitAmount":40000},{"category":"TRANSPORT","discountRate":10.0,"description":"대중교통 할인","limitAmount":10000},{"category":"TAXI","discountRate":0.0,"description":"카카오T 택시 할인","limitAmount":4000}]','2026-09-03 13:30:00' FROM financial_company c WHERE c.company_code='SHINHAN_CARD' AND NOT EXISTS(SELECT 1 FROM financial_product p2 WHERE p2.company_id=c.company_id AND p2.product_type='CARD' AND p2.product_name='카카오뱅크 신한카드 Time');
DELETE o FROM financial_product_option o JOIN financial_product fp ON fp.product_id=o.product_id JOIN financial_company c ON c.company_id=fp.company_id WHERE c.company_code='SHINHAN_CARD' AND fp.product_type='CARD' AND fp.product_name='카카오뱅크 신한카드 Time';
COMMIT;
SELECT p.product_type,COUNT(*) AS product_count FROM financial_product p JOIN financial_company c ON c.company_id=p.company_id JOIN tmp_dodam_compat_products t ON t.company_code=c.company_code AND t.product_type=p.product_type AND t.product_name=p.product_name GROUP BY p.product_type ORDER BY p.product_type;
SELECT COUNT(*) AS option_count FROM financial_product_option o JOIN financial_product p ON p.product_id=o.product_id JOIN financial_company c ON c.company_id=p.company_id JOIN tmp_dodam_compat_products t ON t.company_code=c.company_code AND t.product_type=p.product_type AND t.product_name=p.product_name;
SELECT COUNT(*) AS api_required_product_field_violations FROM financial_product p JOIN financial_company c ON c.company_id=p.company_id JOIN tmp_dodam_compat_products t ON t.company_code=c.company_code AND t.product_type=p.product_type AND t.product_name=p.product_name WHERE (p.product_type='DEPOSIT' AND (p.join_way IS NULL OR p.max_rate IS NULL)) OR (p.product_type='SAVINGS' AND (p.join_way IS NULL OR p.saving_type IS NULL OR p.max_rate IS NULL)) OR (p.product_type='LOAN' AND (p.loan_type IS NULL OR p.min_rate IS NULL OR p.max_rate IS NULL)) OR (p.product_type='CARD' AND (p.baseline_performance IS NULL OR p.max_benefit_limit IS NULL OR p.benefits IS NULL));
SELECT COUNT(*) AS api_required_saving_option_violations FROM financial_product_option o JOIN financial_product p ON p.product_id=o.product_id JOIN financial_company c ON c.company_id=p.company_id JOIN tmp_dodam_compat_products t ON t.company_code=c.company_code AND t.product_type=p.product_type AND t.product_name=p.product_name WHERE p.product_type IN ('DEPOSIT','SAVINGS') AND (o.term IS NULL OR o.rate IS NULL);
SELECT COUNT(*) AS invalid_benefit_json_count FROM financial_product p JOIN financial_company c ON c.company_id=p.company_id JOIN tmp_dodam_compat_products t ON t.company_code=c.company_code AND t.product_type=p.product_type AND t.product_name=p.product_name WHERE p.product_type='CARD' AND p.benefits IS NOT NULL AND JSON_VALID(p.benefits)=0;
SELECT COUNT(*) AS natural_key_duplicates FROM (SELECT c.company_code,p.product_type,p.product_name,COUNT(*) cnt FROM financial_product p JOIN financial_company c ON c.company_id=p.company_id GROUP BY c.company_code,p.product_type,p.product_name HAVING COUNT(*)>1) d;
